'use client'

import { useEffect, useId, useRef, useState } from 'react'
import type { MouseEvent, ReactNode } from 'react'
import './curtain-menu.css'

export interface CurtainMenuItem {
  id: string
  label: string
  href: string
  description?: string
}

export interface CurtainMenuProps {
  items: CurtainMenuItem[]
  activeId?: string
  className?: string
  label?: string
  title?: string
  footer?: ReactNode
  onNavigate?: (id: string, event: MouseEvent<HTMLAnchorElement>) => void
  onOpenChange?: (open: boolean) => void
}

/** A full-screen editorial navigation sheet with native modal behavior. */
export function CurtainMenu({
  items,
  activeId,
  className = '',
  label = 'Explore menu',
  title = 'Where next?',
  footer,
  onNavigate,
  onOpenChange,
}: CurtainMenuProps) {
  const [open, setOpen] = useState(false)
  const openRef = useRef(false)
  const triggerRef = useRef<HTMLButtonElement>(null)
  const dialogRef = useRef<HTMLDialogElement>(null)
  const id = useId()
  const dialogId = `ac-curtain-${id}`
  const titleId = `${dialogId}-title`

  function changeOpen(next: boolean) {
    if (openRef.current === next) return
    openRef.current = next
    setOpen(next)
    onOpenChange?.(next)
  }

  useEffect(() => {
    if (!open) return
    const dialog = dialogRef.current
    if (!dialog) return

    const previousOverflow = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    if (!dialog.open) dialog.showModal()

    return () => {
      if (dialog.open) dialog.close()
      document.body.style.overflow = previousOverflow
      triggerRef.current?.focus({ preventScroll: true })
    }
  }, [open])

  return (
    <div className={`ac-curtain-menu ${className}`.trim()}>
      <button
        ref={triggerRef}
        className="ac-curtain-trigger"
        type="button"
        aria-haspopup="dialog"
        aria-controls={dialogId}
        aria-expanded={open}
        onClick={() => changeOpen(true)}
      >
        <span>{label}</span>
        <span className="ac-curtain-trigger-icon" aria-hidden="true"><i /><i /></span>
      </button>

      <dialog
        ref={dialogRef}
        id={dialogId}
        className="ac-curtain-dialog"
        aria-labelledby={titleId}
        onCancel={(event) => {
          event.preventDefault()
          changeOpen(false)
        }}
        onClose={() => {
          // An effect cleanup may close and immediately reopen in Strict Mode.
          if (!dialogRef.current?.open) changeOpen(false)
        }}
      >
        <div className="ac-curtain-panels" aria-hidden="true"><span /><span /><span /></div>

        <header className="ac-curtain-header">
          <span className="ac-curtain-index"><span aria-hidden="true">✳</span> Navigation index</span>
          <button type="button" className="ac-curtain-close" onClick={() => changeOpen(false)}>
            <span>Close</span>
            <svg viewBox="0 0 20 20" width="20" height="20" fill="none" aria-hidden="true"><path d="m5 5 10 10M15 5 5 15" stroke="currentColor" strokeWidth="1.5" /></svg>
          </button>
        </header>

        <div className="ac-curtain-body">
          <div className="ac-curtain-heading">
            <h2 id={titleId}>{title}</h2>
            <span aria-hidden="true">{String(items.length).padStart(2, '0')} destinations</span>
          </div>

          <nav aria-label={title}>
            <ol className="ac-curtain-links">
              {items.map((item, index) => (
                <li className="ac-curtain-row" key={item.id}>
                  <a
                    className="ac-curtain-link"
                    href={item.href}
                    aria-current={activeId === item.id ? 'page' : undefined}
                    onClick={(event) => {
                      onNavigate?.(item.id, event)
                      changeOpen(false)
                    }}
                  >
                    <span className="ac-curtain-number" aria-hidden="true">{String(index + 1).padStart(2, '0')}</span>
                    <span className="ac-curtain-label">{item.label}</span>
                    {item.description && <span className="ac-curtain-description">{item.description}</span>}
                    <span className="ac-curtain-arrow" aria-hidden="true">↗</span>
                  </a>
                </li>
              ))}
            </ol>
          </nav>

          {footer && <footer className="ac-curtain-footer">{footer}</footer>}
        </div>
      </dialog>
    </div>
  )
}

.ac-curtain-menu {
  --ac-curtain-background: #24251f;
  --ac-curtain-foreground: #f4f2e9;
  --ac-curtain-accent: #f16b43;
  display: inline-flex;
  font-family: inherit;
}

.ac-curtain-trigger,
.ac-curtain-close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  min-height: 48px;
  border: 1px solid currentColor;
  border-radius: 999px;
  padding: 12px 20px;
  font: inherit;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
}

.ac-curtain-trigger {
  color: var(--ac-curtain-foreground);
  background: var(--ac-curtain-background);
}

.ac-curtain-trigger-icon {
  display: grid;
  gap: 5px;
  width: 18px;
}

.ac-curtain-trigger-icon i {
  height: 1px;
  background: currentColor;
}

.ac-curtain-trigger-icon i:last-child { width: 12px; justify-self: end; }

.ac-curtain-dialog {
  position: fixed;
  inset: 0;
  box-sizing: border-box;
  width: 100%;
  height: 100dvh;
  max-width: none;
  max-height: none;
  margin: 0;
  border: 0;
  padding: 0;
  overflow: hidden;
  background: var(--ac-curtain-background);
  color: var(--ac-curtain-foreground);
  font-family: inherit;
}

/* Preserve the browser's hidden state until showModal() adds open. */
.ac-curtain-dialog[open] { display: flex; flex-direction: column; }
.ac-curtain-dialog::backdrop { background: var(--ac-curtain-background); }

.ac-curtain-panels {
  position: absolute;
  z-index: 0;
  inset: 0;
  display: flex;
  pointer-events: none;
  overflow: hidden;
}

.ac-curtain-panels span { flex: 1; background: var(--ac-curtain-accent); transform: translateY(-101%); }
.ac-curtain-dialog[open] .ac-curtain-panels span { animation: ac-curtain-lift 750ms cubic-bezier(.76, 0, .24, 1) both; }
.ac-curtain-dialog[open] .ac-curtain-panels span:nth-child(2) { animation-delay: 60ms; }
.ac-curtain-dialog[open] .ac-curtain-panels span:nth-child(3) { animation-delay: 120ms; }

.ac-curtain-header {
  position: relative;
  z-index: 1;
  display: flex;
  flex: none;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  padding: 24px clamp(20px, 5vw, 80px);
  border-bottom: 1px solid color-mix(in srgb, currentColor 18%, transparent);
}

.ac-curtain-index { display: inline-flex; align-items: center; gap: 12px; font-size: 12px; letter-spacing: .06em; }
.ac-curtain-index > span { color: var(--ac-curtain-accent); font-size: 26px; }
.ac-curtain-close { flex: none; gap: 18px; color: inherit; background: transparent; }
.ac-curtain-close:hover { color: var(--ac-curtain-background); background: var(--ac-curtain-foreground); }

.ac-curtain-body {
  position: relative;
  z-index: 1;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
  padding: 40px clamp(20px, 5vw, 80px) max(32px, env(safe-area-inset-bottom));
}

.ac-curtain-heading { display: flex; align-items: baseline; justify-content: space-between; gap: 24px; margin-bottom: 32px; }
.ac-curtain-heading h2 { margin: 0; font-family: var(--ac-curtain-display-font, Georgia, serif); font-size: clamp(28px, 3.5vw, 54px); font-weight: 400; font-style: italic; letter-spacing: -.035em; }
.ac-curtain-heading > span { font-size: 11px; opacity: .5; letter-spacing: .06em; text-transform: uppercase; }
.ac-curtain-links { margin: 0; padding: 0; list-style: none; }
.ac-curtain-row { border-bottom: 1px solid color-mix(in srgb, currentColor 20%, transparent); overflow: hidden; }
.ac-curtain-row:first-child { border-top: 1px solid color-mix(in srgb, currentColor 20%, transparent); }

.ac-curtain-link {
  display: grid;
  grid-template-columns: 40px minmax(0, 1fr) minmax(0, 180px) 60px;
  align-items: center;
  gap: 16px;
  min-height: 104px;
  padding: 12px 8px;
  color: inherit;
  text-decoration: none;
  transition: color 180ms ease, padding 300ms ease;
}

.ac-curtain-number { align-self: start; padding-top: 12px; font-size: 11px; opacity: .5; }
.ac-curtain-label { min-width: 0; overflow-wrap: anywhere; font-size: clamp(34px, 6.8vw, 100px); font-weight: 400; line-height: 1.05; letter-spacing: -.065em; }
.ac-curtain-description { max-width: 180px; font-size: 12px; line-height: 1.5; opacity: .6; }
.ac-curtain-arrow { grid-column: 4; justify-self: end; font-size: clamp(32px, 4.8vw, 66px); font-weight: 300; line-height: 1; transition: transform 300ms ease; }
.ac-curtain-link[aria-current="page"] .ac-curtain-number { color: var(--ac-curtain-accent); opacity: 1; }
.ac-curtain-link:hover, .ac-curtain-link:focus-visible { color: var(--ac-curtain-accent); padding-left: 18px; }
.ac-curtain-link:hover .ac-curtain-arrow { transform: translate(3px, -3px); }
.ac-curtain-link:focus-visible { outline-offset: -3px; }
.ac-curtain-footer { margin-top: 40px; font-size: 13px; line-height: 1.6; }
.ac-curtain-footer a { color: inherit; text-underline-offset: 4px; }
.ac-curtain-trigger:focus-visible, .ac-curtain-close:focus-visible, .ac-curtain-link:focus-visible, .ac-curtain-footer a:focus-visible { outline: 2px solid var(--ac-curtain-accent); outline-offset: 4px; }
.ac-curtain-link:focus-visible { outline-offset: -3px; }

.ac-curtain-dialog[open] .ac-curtain-heading,
.ac-curtain-dialog[open] .ac-curtain-link,
.ac-curtain-dialog[open] .ac-curtain-footer { animation: ac-curtain-enter 700ms cubic-bezier(.2, .8, .2, 1) 140ms both; }
.ac-curtain-dialog[open] .ac-curtain-row:nth-child(2) .ac-curtain-link { animation-delay: 180ms; }
.ac-curtain-dialog[open] .ac-curtain-row:nth-child(3) .ac-curtain-link { animation-delay: 220ms; }
.ac-curtain-dialog[open] .ac-curtain-row:nth-child(n+4) .ac-curtain-link { animation-delay: 260ms; }

@keyframes ac-curtain-lift { from { transform: translateY(0); } to { transform: translateY(-101%); } }
@keyframes ac-curtain-enter { from { opacity: 0; transform: translateY(44px); } to { opacity: 1; transform: translateY(0); } }

@media (max-width: 600px) {
  .ac-curtain-header { padding-block: 16px; }
  .ac-curtain-index { font-size: 10px; letter-spacing: 0; gap: 8px; }
  .ac-curtain-close { min-width: 44px; min-height: 44px; padding: 10px 14px; gap: 8px; }
  .ac-curtain-body { padding-top: 28px; }
  .ac-curtain-heading { margin-bottom: 24px; }
  .ac-curtain-heading > span { display: none; }
  .ac-curtain-link { grid-template-columns: 24px minmax(0, 1fr) 28px; column-gap: 10px; row-gap: 4px; min-height: 88px; padding-block: 16px; }
  .ac-curtain-label { font-size: clamp(34px, 10vw, 60px); }
  .ac-curtain-description { grid-column: 2; grid-row: 2; max-width: none; font-size: 11px; }
  .ac-curtain-arrow { grid-column: 3; grid-row: 1; font-size: 32px; }
  .ac-curtain-number { padding-top: 6px; }
  .ac-curtain-link:hover, .ac-curtain-link:focus-visible { padding-left: 8px; }
}

@media (prefers-reduced-motion: reduce) {
  .ac-curtain-dialog[open] .ac-curtain-panels span,
  .ac-curtain-dialog[open] .ac-curtain-heading,
  .ac-curtain-dialog[open] .ac-curtain-link,
  .ac-curtain-dialog[open] .ac-curtain-footer { animation: none; }
  .ac-curtain-link, .ac-curtain-arrow { transition: none; }
}
